<?php
namespace App\Services;use App\Models\User;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Http;use Throwable;
class MultichannelNotifier{public function send(User $user,string $event,string $title,string $body,?string $url=null,array $data=[]):void{DB::table('in_app_notifications')->insert(['user_id'=>$user->id,'type'=>$event,'title'=>$title,'body'=>$body,'action_url'=>$url,'data'=>json_encode($data),'created_at'=>now(),'updated_at'=>now()]);$preferences=DB::table('notification_preferences')->where('user_id',$user->id)->first();if($preferences?->whatsapp_enabled&&$user->phone)$this->webhook($user,$event,'whatsapp',$title,$body,$url,config('integrations.whatsapp'));if($preferences?->push_enabled&&DB::table('push_subscriptions')->where('user_id',$user->id)->exists())$this->webhook($user,$event,'push',$title,$body,$url,config('integrations.push'));}private function webhook(User $user,string $event,string $channel,string $title,string $body,?string $url,array $config):void{$status='skipped';$error=null;try{if($config['webhook_url']){Http::withToken((string)$config['token'])->timeout(10)->post($config['webhook_url'],['user_id'=>$user->id,'phone'=>$channel==='whatsapp'?$user->phone:null,'event'=>$event,'title'=>$title,'body'=>$body,'url'=>$url])->throw();$status='sent';}}catch(Throwable $e){$status='failed';$error=mb_substr($e->getMessage(),0,1000);}DB::table('notification_deliveries')->insert(['user_id'=>$user->id,'channel'=>$channel,'event'=>$event,'status'=>$status,'error'=>$error,'created_at'=>now(),'updated_at'=>now()]);}}
